/**
 * The real-world samples' source truth, as counted WITHOUT ERD Studio:
 * copied from each sample's evidence bundle (`.source.expected`, written
 * when the samples were collected for PR #252) and from SOURCE.md. Every
 * count here was made by a standalone script or by hand over the upstream
 * files; the provenance of each is in its comment.
 *
 * The per-table, per-column truth the detailed scorecard compares against
 * is `test/fixtures/real-world-imports/expected.json` (regenerated by the
 * truth scripts; `realWorldImports.scorecard.test.ts` checks it still sums
 * to these counts). This file is the short form the summary scorecard
 * (`scorecardHarness.ts`) reports against.
 *
 * Never edit a number to make a test pass: a count changes only when the
 * sample's upstream files change.
 */

export interface ExpectedCounts {
  tables: number;
  columns: number;
  primaryKeys: number;
  relationships: number;
  /** Descriptions (comments, notes, MS_Description…) on tables and columns the source states. */
  descriptions: number;
}

export interface ExpectedSample {
  importer: 'sql' | 'dbml' | 'semanticModel' | 'dbt';
  counts: ExpectedCounts;
  /** Where the counts come from and how they were made (a summary of the bundle's own `detail`). */
  provenance: string;
}

